-- ---------------------------------------------------------------------------
-- 226  Map 750/751 -- the vehicles were never actually ported
-- ---------------------------------------------------------------------------
-- 65 clone-band creature templates carry a VehicleId. **39 of the 60 distinct
-- ids do not exist in the live Vehicle.dbc**, so those creatures spawn as
-- ordinary NPCs that cannot be ridden at all. 44 templates / ~250 spawns are
-- affected, including quest-critical ones:
--   414 Tendril from Below x79   398 Watch Wind Rider x27   593 Sable Drake x24
--   377 Warsong Shredder x13     391 Astranaar Thrower x12  361 Ashenvale Wrecker x11
--   576 Wings of Steel x10       545 Bilgewater Mortar x9   538 Warsong Assault Wind Rider x8
--
-- WHY THIS WAS INVISIBLE: 196_ (2026-08-01) shipped vehicle 326 + seat 2883,
-- and it IS in `vehicle_dbc` / `vehicleseat_dbc` -- but those are OVERLAY
-- tables the server does not read at runtime, and the binary DBC step was
-- never done. Custom/CSV DBC/Vehicle.csv had 450 rows and did NOT contain 326.
-- So the one vehicle we thought was fixed was never fixed either.
--
-- SOURCE + LAYOUT, both verified rather than assumed:
--   * Vehicle.dbc     -- cata is field-for-field identical (40 fields / 160 B).
--     Confirmed on the 450 ids present in both files: every column agrees on
--     415-450 of them, the differences being Blizzard retuning individual
--     values, with no structural shift. Rows copy VERBATIM.
--     SeatID[8] occupies fields 6..13 (NOT 2..5, which are the
--     turnSpeed/pitchSpeed/pitchMin/pitchMax floats -- reading those as ints
--     yields plausible-looking garbage 'seat ids' like 1070143111).
--   * VehicleSeat.dbc -- cata has 66 fields, we have 58. **The 8 extra fields
--     are APPENDED at 58..65**, so our 0..57 map 1:1 and cata 58..65 are
--     dropped. Verified on the 782 seat ids in both files: for every one of
--     our columns 50..57, ALL non-zero rows agree with the same cata index.
--
--     This CORRECTS the note left by the earlier round, which recorded
--     "our 57 -> cata 63". That was an artifact of a degenerate match: our
--     col 57 (CameraSeatZoomMax) is zero in 781 of 782 rows, and reading an
--     int column as a float yields a denormal ~0, so every all-zero cata
--     column "matched" it. The single non-zero row -- seat 1723, value 50.0 --
--     matches cata 57 and NOT cata 63.
--
-- Field types were taken from the same WDBXEditor definition csv2wdbc packs
-- with, so ints were read as ints and floats as floats instead of guessed.
--
-- BOARDING: 10 vehicles had no npc_spellclick_spells row here while cata has
-- one -- including 3 that are FLAGGED UNIT_NPC_FLAG_SPELLCLICK with no row at
-- all, which is the dead-cursor bug (Rocketway Rat x7, Grit, Wings of Steel
-- x10). Spell 46598 "Ride Vehicle Hardcoded" and 61791 both already resolve;
-- 68726 did not exist anywhere and is minted below (it cleared the
-- effect-id >= 165 guard that crashed the boot in 192_).
--
-- ACCESSORIES: cata defines vehicle_template_accessory for 10 of these and we
-- had ZERO. Only 3 are inserted -- the other 7 name a passenger creature that
-- was never imported here, and a row pointing at a non-existent creature just
-- logs an error and seats nothing. Left out, with the passenger named:
--   3639789 Kristoff's Chain Vehicle -> 39640 Kristoff Manheim
--   3639833 Twilight Buzzard         -> 39835 Twilight Knight Rider
--   3639839 Twilight Stormwaker      -> 39838 Twilight Stormwaker
--   3640190 Climbing Tree            -> 40250
--   3640573 Twilight Stormwaker      -> 40575 Twilight Stormwaker
--   3650089 Julak-Doom               -> 50091 Julak-Doom
--   3734282 Twilight Rider (7 spawns)-> 34293 Twilight Rider (Humanoid)
-- The last one is the visible one: the mount spawns riderless.
--
-- AS WITH 225_, THIS SQL ALONE FIXES NOTHING. The overlay is not read at
-- runtime. The binaries are compiled and verified (0 rows lost) and are in the
-- client archives already; they still need copying to the SERVER's data/dbc:
--     Custom/DBCs/Vehicle.dbc        450 -> 488
--     Custom/DBCs/VehicleSeat.dbc    784 -> 857
-- ---------------------------------------------------------------------------

-- --- 39 vehicles ----------------------------------------------------------
DELETE FROM `vehicle_dbc` WHERE `ID` IN (326, 333, 361, 377, 379, 391, 398, 400, 403, 414, 519, 528, 538, 540, 541, 543, 545, 547, 558, 571, 576, 593, 726, 782, 783, 837, 958, 1031, 1033, 1068, 1131, 1204, 1227, 1295, 1322, 1626, 1627, 1633, 1650);


-- --- 73 seats they reference ---------------------------------------------
DELETE FROM `vehicleseat_dbc` WHERE `ID` IN (2883, 2983, 2984, 2985, 2986, 2987, 3426, 3489, 3490, 3491, 3687, 3689, 3946, 3988, 4046, 4106, 4287, 5946, 6106, 6292, 6346, 6349, 6386, 6388, 6391, 6426, 6528, 6746, 6786, 6787, 7026, 7683, 7791, 7793, 7794, 7801, 7802, 7803, 7804, 7805, 7806, 7807, 7924, 7925, 8195, 8196, 8197, 8369, 8371, 8436, 8581, 8582, 8583, 8584, 8585, 8586, 8587, 8588, 8800, 8858, 9019, 9020, 9021, 9090, 9095, 9096, 9097, 9098, 9906, 9907, 9916, 9952, 10134);


-- --- the one spell a spellclick needs and nothing had ---------------------
DELETE FROM `spell_dbc` WHERE `ID` IN (68726);


-- --- boarding -------------------------------------------------------------
DELETE FROM `npc_spellclick_spells` WHERE `npc_entry` IN (3636437, 3636972, 3637139, 3639789, 3639833, 3639839, 3640573, 3640650, 3650089, 3734282);

-- --- passengers (only those whose creature exists here) -------------------
DELETE FROM `vehicle_template_accessory` WHERE `entry` IN (3636972, 3637139, 3640650);
-- Verify -- after the SERVER dbc deploy and a restart:
--   * no "Creature (Entry: N) has non-existing VehicleId" lines in Errors.log
--   * read_server_dbc Vehicle -> 488 records, 326/377/414 present
--   * read_server_dbc VehicleSeat -> 857 records, 2883 present
--   * clicking a Warsong Shredder / Wings of Steel actually seats you
